def absolute(value):
    if value < 0:
        return -value
    return value

def choose_route(tiles, width, start, blocked, offsets, goals):
    steps = {start: 0}
    first = {}
    frontier = [start]
    best = None
    best_dist = width * len(tiles)
    for cell in frontier:
        distance = steps[cell]
        if distance > best_dist:
            break
        if cell in goals and cell != start:
            if distance < best_dist or goals[0] == cell:
                best = cell
                best_dist = distance
        if distance >= best_dist:
            continue
        for direction in range(4):
            neighbor = cell + offsets[direction]
            if neighbor in steps or (cell == start and neighbor in blocked):
                continue
            if tiles[neighbor // width][neighbor % width] != ".":
                continue
            steps[neighbor] = distance + 1
            if cell == start:
                first[neighbor] = direction
            else:
                first[neighbor] = first[cell]
            frontier.append(neighbor)
    if best is None:
        return "wait"
    return ["up", "right", "down", "left"][first[best]]

def restricted_cells(tiles, width, player, opponents, offsets):
    guard = opponents[2]
    patrol = guard["y"] * width + guard["x"]
    danger = {patrol: True}
    for offset in offsets:
        danger[patrol + offset] = True
    for i in range(2):
        robot = opponents[i]
        position = robot["y"] * width + robot["x"]
        dx = player[0] - robot["x"]
        dy = player[1] - robot["y"]
        if absolute(dx) + absolute(dy) > 2:
            continue
        for offset in offsets:
            next_cell = position + offset
            y = next_cell // width
            x = next_cell % width
            if absolute(player[0] - x) + absolute(player[1] - y) != absolute(dx) + absolute(dy) - 1:
                continue
            if tiles[y][x] == ".":
                danger[next_cell] = True
                if x == player[0] and y == player[1]:
                    danger[position] = True
                break
    return danger

def decide(state):
    tiles = state["tiles"]
    width = len(tiles[0])
    player = state["player"]
    start = player[1] * width + player[0]
    offsets = [-width, 1, width, -1]
    danger = restricted_cells(tiles, width, player, state["opponents"], offsets)
    goals = []
    for battery in state["items"]:
        goals.append(battery["y"] * width + battery["x"])
    if start in goals and start not in danger:
        return "pick"
    if len(goals) == 0:
        exit = state["exit"]
        goals.append(exit[1] * width + exit[0])
    return choose_route(tiles, width, start, danger, offsets, goals)

while True:
    action = decide(scan())
    if action == "pick":
        pick()
    elif action == "wait":
        wait()
    else:
        move(action)
